// Bundled source: orca/repo/src/main/runtime/orchestration/db/schema/create-core-tables-sql.ts
function createCoreTablesSql() {
  return `
CREATE TABLE IF NOT EXISTS runs (
  id                    TEXT PRIMARY KEY,
  objective             TEXT NOT NULL,
  home_database         TEXT NOT NULL DEFAULT 'this_database',
  coordinator_handle    TEXT,
  coordinator_pane_key  TEXT,
  -- Bare Orca session id the coordinator is addressed by, when it has one (today only structured
  -- sessions); for a /clear'd chat, its lineage root's.
  coordinator_orca_session_id TEXT,
  -- The consumer_generation coordinator_orca_session_id was written at; the id counts only while they
  -- are equal (run-coordinator-orca-session). So bump consumer_generation for a rebind or unbind only.
  coordinator_orca_session_id_generation INTEGER,
  consumer_generation   INTEGER NOT NULL DEFAULT 0,
  legacy                INTEGER NOT NULL DEFAULT 0,
  created_at            TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at            TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS messages (
  id            TEXT NOT NULL,
  run_id        TEXT NOT NULL DEFAULT '${LEGACY_RUN_ID}',
  delivery_contract TEXT NOT NULL DEFAULT 'current_delivery'
    CHECK(delivery_contract IN ('legacy_direct', 'current_delivery', 'audit_only')),
  from_handle   TEXT NOT NULL,
  to_handle     TEXT NOT NULL,
  subject       TEXT NOT NULL,
  body          TEXT NOT NULL DEFAULT '',
  type          TEXT NOT NULL DEFAULT 'status'
    CHECK(type IN (
      'status', 'dispatch', 'worker_done', 'merge_ready',
      'escalation', 'handoff', 'decision_gate', 'question', 'heartbeat'
    )),
  priority      TEXT NOT NULL DEFAULT 'normal'
    CHECK(priority IN ('normal', 'high', 'urgent')),
  thread_id     TEXT,
  payload       TEXT,
  read          INTEGER NOT NULL DEFAULT 0,
  sequence      INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  delivered_at  TEXT,
  sender_pane_key TEXT,
  pointer_enter_pending INTEGER NOT NULL DEFAULT 0,
  pointer_pty_id TEXT,
  pointer_process_incarnation TEXT
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_messages_id ON messages(id);
CREATE INDEX IF NOT EXISTS idx_inbox ON messages(to_handle, read);
CREATE INDEX IF NOT EXISTS idx_thread ON messages(thread_id);
CREATE TABLE IF NOT EXISTS run_coordinator_handles (
  run_id          TEXT NOT NULL,
  terminal_handle TEXT NOT NULL,
  first_bound_at  TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (run_id, terminal_handle)
);

CREATE INDEX IF NOT EXISTS idx_run_coordinator_handles_handle
  ON run_coordinator_handles(terminal_handle, run_id);

-- Handle-only on purpose; createRunCoordinatorAddressTriggers replaces both on every open with a
-- form that also remembers the coordinator's session address. This SQL runs before migrate, so it
-- must compile against a pre-v42 runs table: a trigger naming coordinator_orca_session_id there makes
-- the next INSERT INTO runs fail to prepare mid-migration.
CREATE TRIGGER IF NOT EXISTS trg_runs_remember_coordinator_insert
AFTER INSERT ON runs
WHEN NEW.legacy = 0 AND NEW.coordinator_handle IS NOT NULL
BEGIN
  INSERT OR IGNORE INTO run_coordinator_handles (run_id, terminal_handle)
  VALUES (NEW.id, NEW.coordinator_handle);
END;

CREATE TRIGGER IF NOT EXISTS trg_runs_remember_coordinator_update
AFTER UPDATE OF coordinator_handle ON runs
WHEN NEW.legacy = 0 AND NEW.coordinator_handle IS NOT NULL
BEGIN
  INSERT OR IGNORE INTO run_coordinator_handles (run_id, terminal_handle)
  VALUES (NEW.id, NEW.coordinator_handle);
END;

CREATE TRIGGER IF NOT EXISTS trg_runs_forget_coordinator_handles
AFTER DELETE ON runs
BEGIN
  DELETE FROM run_coordinator_handles WHERE run_id = OLD.id;
END;

CREATE TABLE IF NOT EXISTS deliveries (
  id                    TEXT PRIMARY KEY,
  run_id                TEXT NOT NULL,
  -- Default keeps a downgraded binary's column-less INSERT working against a v34 database.
  mailbox_handle        TEXT NOT NULL DEFAULT '',
  consumer_generation   INTEGER NOT NULL,
  message_ids           TEXT NOT NULL,
  status                TEXT NOT NULL DEFAULT 'outstanding'
    CHECK(status IN ('outstanding', 'acknowledged', 'fenced')),
  created_at            TEXT NOT NULL DEFAULT (datetime('now')),
  acknowledged_at       TEXT
);

CREATE INDEX IF NOT EXISTS idx_deliveries_run_created
  ON deliveries(run_id, created_at);

CREATE TABLE IF NOT EXISTS mutation_receipts (
  caller_fingerprint  TEXT NOT NULL,
  request_id          TEXT NOT NULL,
  method              TEXT NOT NULL,
  payload_hash        TEXT NOT NULL,
  state               TEXT NOT NULL DEFAULT 'pending'
    CHECK(state IN ('pending', 'completed')),
  receipt             TEXT,
  created_at          TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at          TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (caller_fingerprint, request_id)
);

CREATE TABLE IF NOT EXISTS mutation_caller_identities (
  transport           TEXT PRIMARY KEY,
  caller_fingerprint  TEXT NOT NULL UNIQUE
);

-- Attempt evidence stays additive so old Task/Dispatch/worker CHECK enums remain wire-compatible.
CREATE TABLE IF NOT EXISTS attempt_observation_facts (
  id                    TEXT PRIMARY KEY,
  dispatch_id           TEXT NOT NULL,
  task_id               TEXT NOT NULL,
  sequence              INTEGER NOT NULL,
  authority_id          TEXT NOT NULL,
  authority_clock       TEXT NOT NULL,
  facet                 TEXT NOT NULL,
  payload               TEXT NOT NULL,
  source_observed_at    INTEGER,
  execution_received_at INTEGER,
  home_received_at      INTEGER NOT NULL,
  created_at            TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(dispatch_id, sequence)
);

CREATE INDEX IF NOT EXISTS idx_attempt_observation_facts_projection
  ON attempt_observation_facts(dispatch_id, facet, sequence);

CREATE TABLE IF NOT EXISTS worker_dispatches (
  dispatch_id            TEXT PRIMARY KEY,
  runtime_epoch          TEXT,
  state                  TEXT NOT NULL DEFAULT 'starting'
    CHECK(state IN (
      'starting', 'ready', 'start_unknown', 'failed', 'succeeded',
      'stopping', 'stop_unknown', 'stopped', 'abandoned'
    )),
  stage                  TEXT NOT NULL DEFAULT 'accepted',
  worktree_id            TEXT,
  agent_terminal_handle  TEXT,
  setup_state            TEXT NOT NULL DEFAULT 'not_applicable',
  effects                TEXT NOT NULL DEFAULT '[]',
  residual_resources     TEXT NOT NULL DEFAULT '[]',
  start_options          TEXT NOT NULL DEFAULT '{}',
  last_error             TEXT,
  created_at             TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at             TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_worker_dispatches_recoverable
  ON worker_dispatches(dispatch_id)
  WHERE state IN ('starting', 'ready', 'start_unknown', 'stopping', 'stop_unknown');

CREATE TABLE IF NOT EXISTS worker_terminal_resources (
  id                       TEXT PRIMARY KEY,
  origin_dispatch_id       TEXT NOT NULL,
  owner_dispatch_id        TEXT NOT NULL,
  prior_owner_dispatch_ids TEXT NOT NULL DEFAULT '[]',
  worktree_id              TEXT,
  terminal_handle          TEXT NOT NULL,
  pane_key                 TEXT,
  process_incarnation      TEXT,
  endpoint_id              TEXT,
  endpoint_incarnation     TEXT,
  host_scope               TEXT,
  ownership_state          TEXT NOT NULL DEFAULT 'owned'
    CHECK(ownership_state IN ('owned', 'transferred', 'user_owned', 'external', 'released')),
  release_state            TEXT NOT NULL DEFAULT 'not_requested'
    CHECK(release_state IN (
      'not_requested', 'retained', 'requested', 'releasing', 'released', 'unknown'
    )),
  retained_reason          TEXT,
  release_requested_at     TEXT,
  release_completed_at     TEXT,
  release_error            TEXT,
  recovery_attempt_count   INTEGER NOT NULL DEFAULT 0,
  last_recovery_at         TEXT,
  archive_source           TEXT,
  archive_status           TEXT,
  auto_release_at          TEXT,
  auto_release_dispatch_id TEXT,
  created_at               TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at               TEXT NOT NULL DEFAULT (datetime('now')),
  -- JSON: the agent conversation a closed worker reopens in (WorkerResumeSession).
  resume_session           TEXT
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_worker_terminal_resources_owner
  ON worker_terminal_resources(owner_dispatch_id);
CREATE INDEX IF NOT EXISTS idx_worker_terminal_resources_handle
  ON worker_terminal_resources(terminal_handle);
CREATE INDEX IF NOT EXISTS idx_worker_terminal_resources_pane
  ON worker_terminal_resources(pane_key);
CREATE INDEX IF NOT EXISTS idx_worker_terminal_resources_identity
  ON worker_terminal_resources(process_incarnation, host_scope);
CREATE INDEX IF NOT EXISTS idx_worker_terminal_resources_release
  ON worker_terminal_resources(release_state);

-- One live agent-session operation id per structured worker mailbox. Persisted because the id is
-- the send's idempotency key: re-minting it after a restart would re-deliver an already-queued
-- pointer as a second turn.
CREATE TABLE IF NOT EXISTS structured_pointer_operations (
  mailbox_handle    TEXT PRIMARY KEY,
  session_id        TEXT NOT NULL,
  operation_id      TEXT NOT NULL,
  batch_fingerprint  TEXT NOT NULL,
  minted_at_ms      INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS worker_terminal_archives (
  dispatch_id   TEXT PRIMARY KEY,
  resource_id   TEXT NOT NULL,
  kind          TEXT NOT NULL CHECK(kind IN ('transcript_pin', 'terminal_tail', 'structured_journal')),
  content       TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

  `;
}

// Bundled source: orca/repo/src/main/runtime/orchestration/db/schema/create-graph-tables-sql.ts
var ADDITIVE_LIFECYCLE_DELETE_TRIGGERS_SQL = `
CREATE TRIGGER IF NOT EXISTS trg_tasks_delete_additive_lifecycle
AFTER DELETE ON tasks
BEGIN
  DELETE FROM attempt_observation_facts WHERE task_id = OLD.id;
END;

CREATE TRIGGER IF NOT EXISTS trg_dispatches_delete_additive_lifecycle
AFTER DELETE ON dispatch_contexts
BEGIN
  DELETE FROM attempt_observation_facts WHERE dispatch_id = OLD.id;
END;
`;
function createGraphTablesSql() {
  return `
CREATE TABLE IF NOT EXISTS federated_dispatches (
  dispatch_id             TEXT PRIMARY KEY,
  environment_id          TEXT NOT NULL,
  environment_name        TEXT NOT NULL,
  peer_fingerprint        TEXT NOT NULL,
  remote_runtime_epoch    TEXT,
  protocol_version        INTEGER NOT NULL DEFAULT 1,
  remote_worktree_id      TEXT,
  remote_terminal_handle  TEXT,
  to_home_imported_sequence INTEGER NOT NULL DEFAULT 0,
  to_home_acknowledged_sequence INTEGER NOT NULL DEFAULT 0,
  home_auto_release_at    TEXT,
  home_auto_release_state TEXT,
  created_at              TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at              TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS remote_dispatch_attachments (
  -- DEFAULT: a rolled-back v1.4.198 host still inserts here without a home Run.
  home_run_id             TEXT NOT NULL DEFAULT '',
  dispatch_id             TEXT PRIMARY KEY,
  task_id                 TEXT NOT NULL,
  home_peer_fingerprint   TEXT NOT NULL,
  protocol_version        INTEGER NOT NULL DEFAULT 1,
  runtime_epoch           TEXT NOT NULL,
  capability_hash         TEXT,
  pane_key                TEXT,
  process_incarnation     TEXT,
  state                   TEXT NOT NULL DEFAULT 'starting'
    CHECK(state IN (
      'starting', 'ready', 'start_unknown', 'failed', 'succeeded',
      'stopping', 'stop_unknown', 'stopped', 'abandoned'
    )),
  stage                   TEXT NOT NULL DEFAULT 'accepted',
  worktree_id             TEXT,
  terminal_handle         TEXT,
  setup_state             TEXT NOT NULL DEFAULT 'not_applicable',
  effects                 TEXT NOT NULL DEFAULT '[]',
  residual_resources      TEXT NOT NULL DEFAULT '[]',
  to_worker_imported_sequence INTEGER NOT NULL DEFAULT 0,
  -- Nesting depth of the worker this attachment represents. Propagated from the
  -- Run home; absent from an old client means 1, which fails closed.
  depth                   INTEGER NOT NULL DEFAULT 1,
  -- Its own counter: a federated worker host has no dispatch_contexts row to borrow one from.
  consumer_generation     INTEGER NOT NULL DEFAULT 0,
  last_error              TEXT,
  created_at              TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at              TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Why five states: 'start_unknown', 'stopping', and 'stop_unknown' do not
-- establish process exit, and a potentially-live worker must still count as a
-- nesting parent. See docs/reference/ssh-execution-boundary.md.
CREATE INDEX IF NOT EXISTS idx_remote_dispatch_attachments_active_pane
  ON remote_dispatch_attachments(pane_key)
  WHERE ${potentiallyLiveRemoteAttachmentSql()};
CREATE INDEX IF NOT EXISTS idx_remote_dispatch_attachments_active_pane_suffix
  ON remote_dispatch_attachments(${REMOTE_ATTACHMENT_PANE_KEY_MATCH_SUFFIX_SQL})
  WHERE ${potentiallyLiveRemoteAttachmentSql()}
    AND pane_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS federation_relay_items (
  dispatch_id   TEXT NOT NULL,
  direction     TEXT NOT NULL CHECK(direction IN ('to_home', 'to_worker')),
  sequence      INTEGER NOT NULL,
  message_id    TEXT NOT NULL,
  kind          TEXT NOT NULL,
  payload       TEXT NOT NULL,
  byte_count    INTEGER NOT NULL,
  acked_at      TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (dispatch_id, direction, sequence),
  UNIQUE (dispatch_id, direction, message_id)
);

CREATE INDEX IF NOT EXISTS idx_federation_relay_pending
  ON federation_relay_items(dispatch_id, direction, acked_at, sequence);

CREATE TABLE IF NOT EXISTS remote_questions (
  message_id        TEXT PRIMARY KEY,
  dispatch_id       TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN ('pending', 'answered', 'closed')),
  answer_message_id TEXT,
  answer_body       TEXT,
  created_at        TEXT NOT NULL DEFAULT (datetime('now')),
  answered_at       TEXT
);

CREATE INDEX IF NOT EXISTS idx_remote_questions_dispatch_status
  ON remote_questions(dispatch_id, status);

-- Deletes from tasks, dispatch_contexts and worker tables are recorded in removed_orchestration_work
-- (removed-orchestration-work-store.ts).
CREATE TABLE IF NOT EXISTS tasks (
  id            TEXT PRIMARY KEY,
  run_id        TEXT NOT NULL DEFAULT '${LEGACY_RUN_ID}',
  parent_id     TEXT,
  created_by_terminal_handle TEXT,
  created_by_pane_key TEXT,
  created_by_process_incarnation TEXT,
  created_by_run_generation INTEGER,
  task_title    TEXT,
  display_name  TEXT,
  spec          TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN (
      'pending', 'ready', 'dispatched',
      'completed', 'failed', 'blocked'
    )),
  deps          TEXT NOT NULL DEFAULT '[]',
  result        TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at  TEXT
);

CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status);
CREATE INDEX IF NOT EXISTS idx_tasks_parent ON tasks(parent_id);

-- Deletes are recorded in removed_orchestration_work (removed-orchestration-work-store.ts).
CREATE TABLE IF NOT EXISTS dispatch_contexts (
  id                  TEXT PRIMARY KEY,
  run_id              TEXT NOT NULL DEFAULT '${LEGACY_RUN_ID}',
  task_id             TEXT NOT NULL,
  contract_version    INTEGER NOT NULL DEFAULT ${CURRENT_CONTRACT_VERSION},
  launch_token_hash   TEXT,
  assignee_handle     TEXT,
  assignee_pane_key   TEXT,
  -- Bare Orca session id the agent is addressed by, when it has one (today only structured
  -- sessions); for a /clear'd chat, its lineage root's. Not its orca_session_id:<id> address.
  assignee_orca_session_id TEXT,
  capability_hash     TEXT,
  process_incarnation TEXT,
  capability_revoked_at TEXT,
  -- R1 identity facts; nullable when legacy provenance was never proven.
  retry_of_dispatch_id TEXT,
  creator_dispatch_id TEXT,
  -- Who created this row. A row whose creator is its own assignee is bookkeeping, not delegation,
  -- so it must not count as a nesting parent. Null on rows written before v37 and for Orca's loop.
  creator_handle      TEXT,
  creator_pane_key    TEXT,
  -- Same form as assignee_orca_session_id: the id the creator is addressed by (a lineage root's).
  creator_orca_session_id TEXT,
  host_scope          TEXT,
  status              TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN ('pending', 'dispatched', 'completed', 'failed', 'circuit_broken')),
  failure_count       INTEGER NOT NULL DEFAULT 0,
  last_failure        TEXT,
  -- Why the process is gone, when Orca could establish it. See TerminalExitCause.
  termination_reason  TEXT,
  -- Nesting depth: a root coordinator's worker is 1, its worker's worker is 2.
  -- Defaults to 1 so an unstamped row fails closed rather than reading as a root.
  depth               INTEGER NOT NULL DEFAULT 1,
  -- Bumped whenever the Dispatch is re-pointed at a pane/process, fencing the prior consumer's
  -- outstanding dispatch mailbox Delivery.
  consumer_generation INTEGER NOT NULL DEFAULT 0,
  dispatched_at       TEXT,
  completed_at        TEXT,
  created_at          TEXT NOT NULL DEFAULT (datetime('now')),
  last_heartbeat_at   TEXT,
  -- The settled Dispatch whose worker this one continues (a follow-up sent to it).
  follow_up_of_dispatch_id TEXT,
  -- Set when the worker reported with coordinator mail unread; cleared once that mail continues it.
  follow_up_mail_at TEXT
);

CREATE INDEX IF NOT EXISTS idx_dispatch_task ON dispatch_contexts(task_id);
CREATE INDEX IF NOT EXISTS idx_dispatch_status ON dispatch_contexts(status);
CREATE INDEX IF NOT EXISTS idx_dispatch_assignee_handle ON dispatch_contexts(assignee_handle);

${ADDITIVE_LIFECYCLE_DELETE_TRIGGERS_SQL}

CREATE TABLE IF NOT EXISTS decision_gates (
  id            TEXT PRIMARY KEY,
  run_id        TEXT NOT NULL DEFAULT '${LEGACY_RUN_ID}',
  task_id       TEXT NOT NULL,
  question      TEXT NOT NULL,
  options       TEXT NOT NULL DEFAULT '[]',
  status        TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN ('pending', 'resolved', 'timeout')),
  resolution    TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  resolved_at   TEXT
);

CREATE INDEX IF NOT EXISTS idx_gates_task ON decision_gates(task_id);
CREATE INDEX IF NOT EXISTS idx_gates_status ON decision_gates(status);

CREATE INDEX IF NOT EXISTS idx_runs_coordinator_pane_leaf
  ON runs(${RUN_PANE_KEY_MATCH_SUFFIX_SQL})
  WHERE coordinator_pane_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS coordinator_runs (
  id                  TEXT PRIMARY KEY,
  spec                TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'idle'
    CHECK(status IN ('idle', 'running', 'completed', 'failed')),
  coordinator_handle  TEXT NOT NULL,
  poll_interval_ms    INTEGER NOT NULL DEFAULT 2000,
  created_at          TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at        TEXT,
  scheduler_lost_at   TEXT
);
  `;
}

// Bundled source: orca/repo/src/main/runtime/orchestration/db/schema/migrate-v41.ts
var OUTSTANDING_MAILBOX_INDEX_SQL = `
  CREATE INDEX IF NOT EXISTS idx_deliveries_one_outstanding
    ON deliveries(mailbox_handle) WHERE status = 'outstanding' AND mailbox_handle != '';
`;
var DERIVED_DELIVERY_SCHEMA_SQL = `
  CREATE VIEW IF NOT EXISTS outstanding_deliveries AS
    SELECT * FROM deliveries
    WHERE status = 'outstanding'
      AND EXISTS (
        SELECT 1 FROM json_each(deliveries.message_ids) AS member
        JOIN messages ON messages.id = member.value WHERE messages.read = 0
      );
  CREATE TRIGGER IF NOT EXISTS trg_deliveries_one_outstanding
    AFTER INSERT ON deliveries
    WHEN NEW.mailbox_handle != '' AND EXISTS (
      SELECT 1 FROM outstanding_deliveries WHERE mailbox_handle = NEW.mailbox_handle LIMIT 1 OFFSET 1
    )
    BEGIN
      SELECT RAISE(ABORT, 'Mailbox already has an outstanding delivery');
    END;
`;
function migrateV41(current) {
  if (current >= 41) {
    return;
  }
  this.db.exec(
    `DROP INDEX IF EXISTS idx_deliveries_one_outstanding;
${OUTSTANDING_MAILBOX_INDEX_SQL}`
  );
}

// Bundled source: orca/repo/src/main/runtime/orchestration/db/reset/removed-orchestration-work-store.ts
var REMOVED_WORK_SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS removed_orchestration_work (
  seq        INTEGER PRIMARY KEY,
  run_id     TEXT,
  kind       TEXT NOT NULL,
  entity_id  TEXT NOT NULL,
  record     TEXT NOT NULL,
  removed_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_removed_orchestration_work_run
  ON removed_orchestration_work(run_id, seq);
CREATE INDEX IF NOT EXISTS idx_removed_orchestration_work_entity
  ON removed_orchestration_work(entity_id, kind);

-- Removals before recorded_since were not recorded; a Run created since then has a complete record.
CREATE TABLE IF NOT EXISTS removed_orchestration_work_coverage (
  singleton      INTEGER PRIMARY KEY CHECK(singleton = 1),
  recorded_since TEXT NOT NULL
);

CREATE TRIGGER IF NOT EXISTS trg_runs_forget_removed_work
AFTER DELETE ON runs
BEGIN
  DELETE FROM removed_orchestration_work WHERE run_id = OLD.id;
END;
`;
function runOfDispatchSql(dispatchIdSql) {
  return `COALESCE(
    (SELECT run_id FROM dispatch_contexts WHERE id = ${dispatchIdSql}),
    (SELECT NULLIF(home_run_id, '') FROM remote_dispatch_attachments WHERE dispatch_id = ${dispatchIdSql}),
    (SELECT run_id FROM removed_orchestration_work
      WHERE entity_id = ${dispatchIdSql} AND kind IN ('dispatch', 'remote_worker')
      ORDER BY seq DESC LIMIT 1)
  )`;
}
var CAPTURE_SPECS = {
  task: {
    table: "tasks",
    entityIdSql: "OLD.id",
    runIdSql: "OLD.run_id",
    fields: {
      parentTaskId: "OLD.parent_id",
      title: "COALESCE(OLD.task_title, OLD.display_name)",
      createdByHandle: "OLD.created_by_terminal_handle",
      createdByPaneKey: "OLD.created_by_pane_key",
      deps: "OLD.deps",
      status: "OLD.status",
      createdAt: "OLD.created_at"
    }
  },
  dispatch: {
    table: "dispatch_contexts",
    entityIdSql: "OLD.id",
    runIdSql: "OLD.run_id",
    fields: {
      taskId: "OLD.task_id",
      retryOfDispatchId: "OLD.retry_of_dispatch_id",
      creatorDispatchId: "OLD.creator_dispatch_id",
      creatorHandle: "OLD.creator_handle",
      creatorPaneKey: "OLD.creator_pane_key",
      creatorOrcaSessionId: "OLD.creator_orca_session_id",
      assigneeHandle: "OLD.assignee_handle",
      assigneePaneKey: "OLD.assignee_pane_key",
      assigneeOrcaSessionId: "OLD.assignee_orca_session_id",
      hostScope: "OLD.host_scope",
      depth: "OLD.depth",
      status: "OLD.status",
      terminationReason: "OLD.termination_reason",
      createdAt: "OLD.created_at"
    }
  },
  worker: {
    table: "worker_dispatches",
    entityIdSql: "OLD.dispatch_id",
    runIdSql: runOfDispatchSql("OLD.dispatch_id"),
    fields: {
      state: "OLD.state",
      stage: "OLD.stage",
      worktreeId: "OLD.worktree_id",
      terminalHandle: "OLD.agent_terminal_handle",
      createdAt: "OLD.created_at"
    }
  },
  terminal: {
    table: "worker_terminal_resources",
    entityIdSql: "OLD.id",
    runIdSql: `COALESCE(${runOfDispatchSql("OLD.owner_dispatch_id")}, ${runOfDispatchSql("OLD.origin_dispatch_id")})`,
    fields: {
      originDispatchId: "OLD.origin_dispatch_id",
      ownerDispatchId: "OLD.owner_dispatch_id",
      priorOwnerDispatchIds: "OLD.prior_owner_dispatch_ids",
      terminalHandle: "OLD.terminal_handle",
      paneKey: "OLD.pane_key",
      worktreeId: "OLD.worktree_id",
      hostScope: "OLD.host_scope",
      ownershipState: "OLD.ownership_state",
      releaseState: "OLD.release_state",
      createdAt: "OLD.created_at"
    }
  },
  remote_worker: {
    table: "remote_dispatch_attachments",
    entityIdSql: "OLD.dispatch_id",
    runIdSql: "NULLIF(OLD.home_run_id, '')",
    fields: {
      taskId: "OLD.task_id",
      homePeerFingerprint: "OLD.home_peer_fingerprint",
      state: "OLD.state",
      stage: "OLD.stage",
      worktreeId: "OLD.worktree_id",
      terminalHandle: "OLD.terminal_handle",
      paneKey: "OLD.pane_key",
      depth: "OLD.depth",
      createdAt: "OLD.created_at"
    }
  },
  federated_worker: {
    table: "federated_dispatches",
    entityIdSql: "OLD.dispatch_id",
    runIdSql: runOfDispatchSql("OLD.dispatch_id"),
    fields: {
      environmentId: "OLD.environment_id",
      environmentName: "OLD.environment_name",
      remoteWorktreeId: "OLD.remote_worktree_id",
      remoteTerminalHandle: "OLD.remote_terminal_handle",
      dispatchStatus: "(SELECT status FROM dispatch_contexts WHERE id = OLD.dispatch_id)",
      createdAt: "OLD.created_at"
    }
  }
};
var CAPTURE_KINDS = [
  "task",
  "dispatch",
  "worker",
  "terminal",
  "remote_worker",
  "federated_worker"
];
var triggerName = (kind) => `trg_${CAPTURE_SPECS[kind].table}_record_removed_work`;
var DROP_REMOVED_WORK_TRIGGERS_SQL = CAPTURE_KINDS.map(
  (kind) => `DROP TRIGGER IF EXISTS ${triggerName(kind)};`
).join("\n");
function captureTriggerSql(kind) {
  const spec = CAPTURE_SPECS[kind];
  const lineageFields = REMOVED_WORK_LINEAGE_FIELDS[kind];
  const fields = Object.entries(spec.fields).map(
    ([key, sql]) => `'${key}', CAST(${sql} AS ${lineageFields[key] === REMOVED_WORK_INT_FIELD ? "INTEGER" : "TEXT"})`
  );
  return `CREATE TRIGGER ${triggerName(kind)}
AFTER DELETE ON ${spec.table}
BEGIN
  INSERT INTO removed_orchestration_work (run_id, kind, entity_id, record)
  VALUES (CAST(${spec.runIdSql} AS TEXT), '${kind}', COALESCE(CAST(${spec.entityIdSql} AS TEXT), ''),
    json_object('v', 1, ${fields.join(", ")}));
END;`;
}
function isRemovedWorkCaptureIntact(db) {
  const names = CAPTURE_KINDS.map((kind) => `'${triggerName(kind)}'`).join(", ");
  const row = db.prepare(
    `SELECT COUNT(*) AS n FROM sqlite_master WHERE type = 'trigger' AND name IN (${names})`
  ).get();
  return Number(row?.n) === CAPTURE_KINDS.length;
}
var MOVED_RECORDED_SINCE_SQL = `MAX(datetime('now'), COALESCE(
  (SELECT datetime(MAX(created_at), '+1 second') FROM runs WHERE legacy = 0), ''))`;
function installRemovedWorkCapture(db, captureWasIntact) {
  db.exec("BEGIN IMMEDIATE");
  try {
    db.exec(`
      ${DROP_REMOVED_WORK_TRIGGERS_SQL}
      ${CAPTURE_KINDS.map(captureTriggerSql).join("\n")}
      INSERT OR ${captureWasIntact ? "IGNORE" : "REPLACE"} INTO removed_orchestration_work_coverage
        (singleton, recorded_since)
        VALUES (1, ${captureWasIntact ? "datetime('now')" : MOVED_RECORDED_SINCE_SQL});
    `);
    db.exec("COMMIT");
  } catch (error62) {
    db.exec("ROLLBACK");
    throw error62;
  }
}

