import { chmodSync, existsSync as existsSync2 } from "node:fs";
function hardenSqliteDatabaseFiles(dbPath) {
  if (dbPath === ":memory:" || process.platform === "win32") {
    return;
  }
  for (const path of [dbPath, `${dbPath}-wal`, `${dbPath}-shm`]) {
    try {
      if (existsSync2(path)) {
        chmodSync(path, 384);
      }
    } catch {
    }
  }
}

